text:
.select-all-button {
  display: flex;
  align-items: center;
  user-select: none;

  & input[type="checkbox"] {
    content: var(--icon-checkbox) !important;
    background: none;
    color: currentColor;
    fill: currentColor;
    stroke: currentColor;
    fill-opacity: 0;
    stroke-opacity: 0;
    -moz-context-properties: fill, fill-opacity, stroke, stroke-opacity;
    border: none;

    &:checked {
      fill-opacity: 1;
      background: none;
    }

    &:indeterminate {
      stroke-opacity: 1;
      background: none;
    }
  }
}
